phase1.code:
fn main() {
    // Immutable (default)
    let name = "Hero";
    let health = 100;
    let is_alive = true;

    // Mutable (explicit)
    let mut score = 0;
    score = 10;
    score = 20;

    // Shadowing
    let x = 5;
    let x = x + 10;  // New variable shadows the old one

    // Constants
    const MAX_HEALTH: i32 = 100;
    const GAME_TITLE: &str = "Rust Arena";

    println!("Name: {}", name);
    println!("Health: {}", health);
    println!("Alive: {}", is_alive);
    println!("Score: {}", score);
    println!("x: {}", x);
    println!("Max Health: {}", MAX_HEALTH);
    println!("Game: {}", GAME_TITLE);
}

